#!/bin/bash
# Generated by care-pi from /etc/care-pi/config.yaml. Do not edit.
# Build one FE plug bundle (docs/solutions.md, section 13.2). The same recipe runs in CI (solution-lock.yml).
# Input (environment): PLUG_REPO (OWNER/NAME on github.com; "." is the repository of care-pi), PLUG_SHA (40 hex),
# PLUG_SLUG, PLUG_SCRIPT (npm script), PLUG_OUT (output directory), PLUG_ENTRY (path of remoteEntry.js in the
# output), PLUG_PATH (optional: the directory of the plug in the repository; npm and PLUG_OUT are relative to it).
# Paths: SRC (default /build/<slug>/src), CACHE (/build/npm-cache), OUT (/out/<slug>/<sha12>).
set -euo pipefail
: "${PLUG_REPO:?}" "${PLUG_SHA:?}" "${PLUG_SLUG:?}"
PLUG_SCRIPT="${PLUG_SCRIPT:-build}"
PLUG_OUT="${PLUG_OUT:-dist}"
PLUG_ENTRY="${PLUG_ENTRY:-assets/remoteEntry.js}"
PLUG_PATH="${PLUG_PATH:-}"
# An in-repo plug (S73): "." is the repository of care-pi; the root of its archive is the checkout root.
if [ "$PLUG_REPO" = "." ]; then
  PLUG_REPO="rithviknishad/care-pi"
fi
if [ -n "$PLUG_PATH" ]; then
  case "/${PLUG_PATH}/" in
    */../* | */./* | *//*) echo "care-pi: PLUG_PATH ${PLUG_PATH} is not a relative directory" >&2; exit 2 ;;
  esac
fi
SHA12="${PLUG_SHA:0:12}"
SRC="${SRC:-/build/${PLUG_SLUG}/src}"
CACHE="${CACHE:-/build/npm-cache}"
OUT="${OUT:-/out/${PLUG_SLUG}/${SHA12}}"

# Download a URL to stdout. The node image has no curl, so use the fetch of Node (as fe-build.sh).
fetch() {
  node -e '
const { Readable } = require("node:stream");
const { pipeline } = require("node:stream/promises");
(async () => {
  const res = await fetch(process.argv[1], { headers: { "User-Agent": "care-pi-plug-build" } });
  if (!res.ok) throw new Error("HTTP " + res.status + " for " + process.argv[1]);
  await pipeline(Readable.fromWeb(res.body), process.stdout);
})().catch((err) => { console.error("care-pi: " + err.message); process.exit(1); });
' "$1"
}

if [ "$(cat "${SRC}/.care-pi-sha" 2>/dev/null || true)" != "$PLUG_SHA" ]; then
  rm -rf "$SRC"
  mkdir -p "$SRC"
  fetch "https://codeload.github.com/${PLUG_REPO}/tar.gz/${PLUG_SHA}" | tar -xz -C "$SRC" --strip-components=1
  echo "$PLUG_SHA" > "${SRC}/.care-pi-sha"
fi
cd "$SRC/${PLUG_PATH:-.}"
npm ci --no-audit --no-fund --prefer-offline --cache "$CACHE"
npm run "$PLUG_SCRIPT" -- --base "/plugs/${PLUG_SLUG}/${SHA12}/"
test -f "${PLUG_OUT}/${PLUG_ENTRY}"
rm -rf "${OUT}.tmp"
mkdir -p "$(dirname "$OUT")"
cp -a "$PLUG_OUT" "${OUT}.tmp"
path_json=""
if [ -n "$PLUG_PATH" ]; then
  path_json="$(printf ', "path": "%s"' "$PLUG_PATH")"
fi
printf '{"slug": "%s", "repo": "https://github.com/%s", "sha": "%s", "entry": "%s"%s, "built_at": "%s"}\n' \
  "$PLUG_SLUG" "$PLUG_REPO" "$PLUG_SHA" "$PLUG_ENTRY" "$path_json" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "${OUT}.tmp/care-pi-plug.json"
rm -rf "$OUT"
mv "${OUT}.tmp" "$OUT"
echo "built ${PLUG_SLUG} ${SHA12}"
